function Get-Sha([byte[]]$b){$h=[Security.Cryptography.SHA256]::Create();try{-join($h.ComputeHash($b)|%{$_.ToString('x2')})}finally{$h.Dispose()}}
function Lock([string]$p){$s=[IO.File]::Open([IO.Path]::GetFullPath($p),[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$m=New-Object IO.MemoryStream;try{$s.CopyTo($m);$b=$m.ToArray()}finally{$m.Dispose()};$t=[Text.UTF8Encoding]::new($false,$true).GetString($b);if($t.Length-and$t[0]-eq[char]0xfeff){$t=$t.Substring(1)};[pscustomobject]@{stream=$s;sha256=(Get-Sha $b);text=$t}}catch{$s.Dispose();throw}}
