 if($gate.status-ne'pass'-or$gate.fresh_launch_authorized-ne$true-or$gate.run_id_prefix-ne$prefix-or(@($gate.seeds)-join'|')-ne($seeds-join'|')-or(@($gate.expected_children)-join'|')-ne($children-join'|')){throw 'Canonical r13 gate identity failed'}
