 foreach($b in @($gate.source_bindings)){$name=[string]$b.name;$path=[IO.Path]::GetFullPath([string]$b.path);if($bindings.ContainsKey($name)-or[string]$b.sha256-notmatch'^[0-9a-f]{64}$'){throw 'Invalid source binding'};if($expectedPaths.ContainsKey($name)-and-not$path.Equals([string]$expectedPaths[$name],[StringComparison]::OrdinalIgnoreCase)){throw "Source binding path mismatch: $name"};$l=Lock $path;if($l.sha256-ne[string]$b.sha256){$l.stream.Dispose();throw "Source binding changed: $name"};$held+=$l.stream;$bindings[$name]=$l};foreach($n in $expectedPaths.Keys){if(!$bindings.ContainsKey($n)){throw "Required source binding absent: $n"}}
 $confirmationBindings=@{};foreach($p in $confirm.source_sha256.PSObject.Properties){if($confirmationBindings.ContainsKey($p.Name)-or[string]$p.Value-notmatch'^[0-9a-f]{64}$'){throw 'Invalid confirmation source binding'};$confirmationBindings[$p.Name]=[string]$p.Value};if($confirmationBindings.Count-ne$bindings.Count){throw 'Confirmation source binding closure is incomplete'};foreach($name in $bindings.Keys){if(!$confirmationBindings.ContainsKey($name)-or$bindings[$name].sha256-ne$confirmationBindings[$name]){throw "Confirmation source binding failed: $name"}}
 . $helperPath
